import math

# ---------------------------------------------------------------------------
# T2cc  |  mStop = 850 GeV  |  DeltaM = 10 15 20 25 30 40 50 60 70 80
# Generated by work/fragments/make_fragments.py (baseline: approved McM request NPS-RunIII2024Summer24FSGenPremix-00007)
# ---------------------------------------------------------------------------

